    Write-Warning "⚠️ BOOT STALE — boot file shows run $bootRunFromFile, git shows run $bootRunFromGit. Trusting git (L29)."
}

Write-Host "STAGE 4 ✓ BOOT: run=$bootRunFromGit | mission=$activeMission | flags=$openFlagsCount"
