$D1 = "https://soul-logger.mrmichaelhobbs123.workers.dev"
$run = 44
$sessionId = "sov100-roman-run$run"

$getResp = try { Invoke-RestMethod "$D1/api/soul/session/$sessionId" -Method Get -TimeoutSec 15 } catch { $null }

if ($getResp -and $getResp.prompts -and $getResp.prompts.Count -gt 0) {
    $dnaCount = $getResp.prompts.Count
    $dnaEndpoint = "GET /api/soul/session/$sessionId"
    Write-Host "STAGE 3 ✓ DNA: $dnaCount prompts via $dnaEndpoint"
} else {
    $dnaCount = 0
    $dnaEndpoint = "NONE"
    Write-Host "STAGE 3 ⚠ DNA_GAP — 0 records"
}

$dnaPath = "D:\OB-1-CANONICAL\CANON\SOUL\EXTRACT\dna-run$run.json"
if (-not (Test-Path "D:\OB-1-CANONICAL\CANON\SOUL\EXTRACT")) { New-Item -ItemType Directory -Path "D:\OB-1-CANONICAL\CANON\SOUL\EXTRACT" -Force | Out-Null }
@{ session_id=$sessionId; run=$run; dna_count=$dnaCount; endpoint=$dnaEndpoint; extracted_at=(Get-Date -Format 'o') } | ConvertTo-Json | Set-Content $dnaPath -Encoding UTF8
Write-Host "  written: $dnaPath"

$repo = "D:\OB-1-CANONICAL"
$run = 44
$starmapDir = "$repo\CANON\STARMAP"
$ledgerHash = "e9bc9228fc2bf147"

$starmapLine = "$(Get-Date -Format 'yyyy-MM-ddTHH:mm:ss') | run$run | HL-219 | sov100-roman-run$run | 3303 chars | $ledgerHash..."
$starmapPath = "$starmapDir\starmap-run$run.txt"
$starmapLine | Set-Content $starmapPath -Encoding UTF8
Write-Host "STAGE 5 ✓ STARMAP: $starmapPath"

# STAGE 6 — KEYWORDS
$keywordDir = "$repo\CANON\SOUL-KEYWORDS"
$idxPath = "$keywordDir\inverted-index.json"

$keywords = @("soul", "dna", "rrl", "blueprint", "pipeline", "phase0", "battlefield", "soulsearch", "registry", "soulkeys", "starmap", "ledger", "reincarnation", "fidelity", "hollow", "real", "missing", "search", "capture", "transcript", "verbatim", "headwater", "extraction", "kilo", "skills")

$inverted = if (Test-Path $idxPath) {
    $raw = Get-Content $idxPath -Raw
    try { $raw | ConvertFrom-Json -AsHashtable } catch { @{} }
} else { @{} }

